void copy_forward(int* dst, const int* src, std::size_t n) {
    for (std::size_t i = 0; i < n; ++i) dst[i] = src[i];
}

void move_range(int* dst, const int* src, std::size_t n) {
    for (std::size_t i = 0; i < n; ++i) dst[i] = src[i];
}

